/**
 * The skill map (owner decision, ADR-050, ADR-061, ADR-115, docs/JOBS_AND_SKILLS.md). GENERATED by a
 * hex layout: 8 branches as directions around the centre, radius 7. Keys are stored per
 * player and must never change; names and descriptions live in messages/*.json under "skills".
 *
 * Skills are learned in order (ADR-115): every skill names the skills that come before it (`requires`,
 * always neighbours on the map). Only the eight basics need nothing. Pure data, no imports.
 */

export const SKILL_BRANCHES = ["it", "finance", "law", "craft", "sales", "management", "science", "logistics"] as const;
export type SkillBranch = (typeof SKILL_BRANCHES)[number];

/** Branch order around the map, clockwise from the right. */
export const MAP_ORDER: readonly SkillBranch[] = [
  "it",
  "finance",
  "law",
  "management",
  "sales",
  "logistics",
  "craft",
  "science",
];

export interface SkillNodeConfig {
  readonly key: string;
  /** One branch, or two for hybrid skills (they count for both). */
  readonly branches: readonly SkillBranch[];
  /** 1 = basics … 5 = mastery. Cost and branch score follow the tier. */
  readonly tier: number;
  /** Axial hex coordinates (pointy top). */
  readonly q: number;
  readonly r: number;
  /**
   * Skills that must be learned first (all of them; neighbouring fields). Empty for the basics. Hybrids of two
   * areas that touch both need one skill from each.
   */
  readonly requires: readonly string[];
}

